using System.Collections.Immutable;
using System.Text;
using Norse.Abstractions.Emit;

namespace Norse.Infrastructure.Web.Server.Generator;

static class ServerRegistrationEmitter
{
	internal static string Emit(string rootNamespace, ImmutableArray<ServiceModel> services, ImmutableArray<string> payloads)
	{
		StringBuilder builder = new();
		builder.AppendCSharp(
			$$"""
			// <auto-generated/>
			namespace {{rootNamespace}};

			#pragma warning disable CS1591 // Generated registration: no XML doc comments.
			/// <summary>Generated by Norse.Infrastructure.Web.Server.Generator — compile-time gRPC service registration with gRPC-Web enabled.</summary>
			public static class NorseGrpcServerRegistration
			{
				/// <summary>Registers the Outcome&lt;T&gt; passthrough surrogates, idempotent per type and safe under concurrent first call.</summary>
				public static void RegisterNorseOutcomeSurrogates() =>
					global::Norse.Infrastructure.Web.Grpc.WireModelRegistrationGuard.EnsureRegistered(
						global::ProtoBuf.Meta.RuntimeTypeModel.Default,
						typeof(NorseGrpcServerRegistration),
						() =>
						{
							var model = global::ProtoBuf.Meta.RuntimeTypeModel.Default;
							global::Norse.Infrastructure.Web.Grpc.IdentifierSerializers.Register(model);
							global::Norse.Infrastructure.Web.Grpc.ResultSerializers.Register(model);
			{{SurrogateGuards(payloads)}}
						});

				/// <summary>Maps every discovered Norse gRPC service with gRPC-Web enabled, registering surrogates first.</summary>
				public static global::Microsoft.AspNetCore.Builder.WebApplication MapNorseGrpcServices(
					this global::Microsoft.AspNetCore.Builder.WebApplication app)
				{
					RegisterNorseOutcomeSurrogates();
					global::Microsoft.AspNetCore.Builder.GrpcWebApplicationBuilderExtensions.UseGrpcWeb(app,
						new global::Microsoft.AspNetCore.Builder.GrpcWebOptions { DefaultEnabled = false });
			{{MapServices(services)}}
					return app;
				}
			}
			#pragma warning restore CS1591
			""");
		return builder.ToString();
	}

	static string SurrogateGuards(ImmutableArray<string> payloads) =>
		string.Join("\n", payloads.Select(p =>
			$"\t\tif (!model.IsDefined(typeof(global::Norse.Abstractions.Contracts.Outcome<{p}>)))\n" +
			$"\t\t\tmodel.Add(typeof(global::Norse.Abstractions.Contracts.Outcome<{p}>), applyDefaultBehaviour: false).SetSurrogate(typeof({p}));"));

	static string MapServices(ImmutableArray<ServiceModel> services) =>
		string.Join("\n", services.Select(s =>
			$"\t\tglobal::Microsoft.AspNetCore.Builder.GrpcWebEndpointConventionBuilderExtensions.EnableGrpcWeb(\n" +
			$"\t\t\tglobal::Microsoft.AspNetCore.Builder.GrpcEndpointRouteBuilderExtensions.MapGrpcService<{s.ImplementationTypeName}>(app));"));
}
